function contours(a,n,tol){const edges=new Map(),stride=n+1;function edge(x,y,xx,yy){let k=y*stride+x,list=edges.get(k)||[];list.push(yy*stride+xx);edges.set(k,list)}for(let y=0;y<n;y++)for(let x=0;x<n;x++){let i=y*n+x;if(!a[i])continue;if(!y||!a[i-n])edge(x,y,x+1,y);if(x===n-1||!a[i+1])edge(x+1,y,x+1,y+1);if(y===n-1||!a[i+n])edge(x+1,y+1,x,y+1);if(!x||!a[i-1])edge(x,y+1,x,y)}let loops=[];while(edges.size){const start=edges.keys().next().value;let p=start,pts=[],prev=null;do{pts.push([p%stride,Math.floor(p/stride)]);let options=edges.get(p);if(!options)throw Error('Open boundary');let index=0;if(options.length>1&&prev!==null){let dx=p%stride-prev%stride,dy=Math.floor(p/stride)-Math.floor(prev/stride);index=options.findIndex(v=>dx*(Math.floor(v/stride)-Math.floor(p/stride))-dy*(v%stride-p%stride)>0);if(index<0)index=0}let next=options.splice(index,1)[0];if(!options.length)edges.delete(p);prev=p;p=next}while(p!==start);if(pts.length>=4){let reduced=simplify(pts,tol);loops.push(reduced.length>=3?reduced:pts)}}return loops}
